def search_matrix(mat: list[list[int]], target: int) -> bool:
    if not mat or not mat[0]:
        return False
    n, m = len(mat), len(mat[0])
    lo, hi = 0, n * m - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        val = mat[mid // m][mid % m]
        if val == target:
            return True
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False
